<script setup lang="ts">
import { computed, onBeforeUnmount, ref, shallowRef, watch } from 'vue'
import { loadNcepManifest, ncepAsset, ncepSvgBlob, NCEP_CHARTS, type NcepManifest } from '../data/ncep'
import { clearRequestCache } from '../data/request-cache'
const props=withDefaults(defineProps<{model?:'gefs'|'aigefs';mode?:'basin'|'typhoon';active?:boolean}>(),{mode:'basin',active:true})
const manifest=shallowRef<NcepManifest>(),modelChoice=ref('GEFS'),run=ref('latest'),product=ref(props.mode==='typhoon'?'track':'region'),region=ref('wp'),storm=ref('WP292026'),error=ref(''),loading=ref(false),loaded=ref(''),zoom=ref(100),frame=ref<HTMLElement>(),exporting=ref(false)
const model=computed(()=>props.model?.toUpperCase()??modelChoice.value)
const records=computed(()=>manifest.value?.records.filter(r=>r.model===model.value).sort((a,b)=>b.run.localeCompare(a.run))??[])
const record=computed(()=>run.value==='latest'?records.value[0]:records.value.find(r=>r.run===run.value))
const pair=computed(()=>{const r=record.value;return !r?undefined:product.value==='region'?r.regions.find(v=>v.id===region.value):r.storms.find(v=>v.id===storm.value)?.[product.value as 'track'|'wind'|'pressure']})
const image=computed(()=>{try{return record.value&&pair.value?ncepAsset(pair.value.png,record.value):''}catch{return ''}})
const labels:Record<string,string>={world:'全球',wp:'西北太平洋',ep:'东北太平洋',al:'大西洋',ni:'北印度洋',si:'南印度洋',sp:'南太平洋'}
const states:Record<string,string>={pending:'待生成／未出版',available:'已出版',partial:'部分出版',unavailable:'未能验证',not_needed:'使用原生genesis'}
let controller:AbortController|undefined,download:AbortController|undefined,revision=0
async function refresh(force=false){controller?.abort();if(!props.active)return;const token=++revision;controller=new AbortController();loading.value=true;error.value='';if(force)clearRequestCache(fetch,NCEP_CHARTS+'index.json');try{const v=await loadNcepManifest(controller.signal);if(token===revision)manifest.value=v}catch(e){if(token===revision&&!controller.signal.aborted)error.value=e instanceof Error?e.message:String(e)}finally{if(token===revision)loading.value=false}}
watch(()=>props.model,()=>{run.value='latest'})
watch(image,()=>{loaded.value='';error.value='';zoom.value=100;download?.abort()},{flush:'sync'})
watch(()=>props.active,a=>{if(a)void refresh();else{++revision;controller?.abort();download?.abort();loading.value=false;releaseFullscreen()}},{immediate:true})
function onImage(event:Event){const img=event.target as HTMLImageElement;if(img.currentSrc===image.value||img.src===image.value)loaded.value=image.value}
async function saveSvg(){const r=record.value,p=pair.value;if(!r||!p)return;download?.abort();const active=new AbortController();download=active;exporting.value=true;const timer=setTimeout(()=>active.abort(),25000);try{const blob=await ncepSvgBlob(ncepAsset(p.svg,r),active.signal);active.signal.throwIfAborted();const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=p.svg.split('/').pop()!.replace(/\.svgz$/,'.svg');a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}catch(e){if(!active.signal.aborted)error.value=e instanceof Error?e.message:String(e)}finally{clearTimeout(timer);if(download===active)exporting.value=false}}
function fullscreen(){if(document.fullscreenElement)void document.exitFullscreen();else void frame.value?.requestFullscreen?.()}
function releaseFullscreen(){if(frame.value&&document.fullscreenElement===frame.value)void document.exitFullscreen?.().catch(()=>{})}
onBeforeUnmount(()=>{++revision;controller?.abort();download?.abort();releaseFullscreen()})
</script>
<template>
<section class="ncep-published" :data-model="model" aria-label="Workflow generated GEFS AIGEFS charts" ref="frame">
<header><h3>{{ model }} · workflow 预制集合图</h3><button :disabled="loading" @click="refresh(true)">刷新发布清单</button></header>
<div class="ncep-controls"><label v-if="!props.model">模型<select v-model="modelChoice" @change="run='latest'" aria-label="Published NCEP model"><option>GEFS</option><option>AIGEFS</option></select></label><label>实际起报 UTC<select v-model="run" aria-label="Published NCEP initialization"><option value="latest">最新已出版起报</option><option v-for="r in records" :key="r.run" :value="r.run">{{ r.run }}</option></select></label><label>图种<select v-model="product" aria-label="Published NCEP product"><option value="region">洋区轨迹／生成候选</option><option value="track">已编号系统成员路径</option><option value="wind">已编号系统原生风速 kt</option><option value="pressure">已编号系统气压 hPa</option></select></label><label v-if="product==='region'">洋区<select v-model="region" aria-label="Published NCEP basin"><option v-for="r in record?.regions??[]" :key="r.id" :value="r.id">{{ labels[r.id]??r.label }}</option></select></label><label v-else>原始系统编号<select v-model="storm" aria-label="Published NCEP cyclone"><option v-for="s in record?.storms??[]" :key="s.id" :value="s.id">{{ s.id }} · {{ s.members }}/31 成员</option></select></label></div>
<p v-if="loading" role="status">读取 workflow 已发布清单，不下载原生格点…</p><p v-if="error" class="ncep-error" role="alert">{{ error }}</p>
<template v-if="record"><p class="ncep-status">起报 {{ record.run }} · 完整 +0–{{ record.horizonHours }}h · tracker {{ record.trackerMembers }}/31 · {{ model==='GEFS'?`原生genesis ${record.genesisMembers}/31`:`场L ${states[record.derived.status]??record.derived.status} · ${record.derived.fields}/1271 成员时次` }} · 产图 {{ record.generatedAt }}</p>
<nav v-if="image&&pair"><a :href="image" :download="pair.png.split('/').pop()" target="_blank" rel="noopener">原尺寸 PNG／长按保存</a><button :disabled="exporting" @click="saveSvg">下载真实 SVG</button><a :href="ncepAsset(record.csv,record)" target="_blank" rel="noopener">全模型原始 CSV</a><a :href="ncepAsset(record.data,record)" target="_blank" rel="noopener">来源 JSON</a><button @click="fullscreen">全屏</button><label>缩放<select v-model.number="zoom" aria-label="Published NCEP zoom"><option v-for="n in [100,150,200,300,400]" :key="n" :value="n">{{ n }}%</option></select></label></nav>
<div v-if="image" class="ncep-image-scroll"><img :key="image" :src="active?image:undefined" v-show="loaded===image" :style="{width:zoom+'%',maxWidth:'none',maxHeight:zoom===100?'min(62vh,520px)':'none',objectFit:'contain'}" :alt="`${model} ${record.run} ${product==='region'?labels[region]:storm} ${product}`" @load="onImage" @error="error='所选成图未能读取；不显示其他模型、系统或旧图代替'"/><p v-if="loaded!==image&&!error" role="status">读取所选成图…</p></div><p v-else class="ncep-error">此模型／起报／系统尚未出版成图，不改用其他选择。</p>
</template><p v-else-if="!loading&&!error">此模型／起报尚未出版成图，不借其他模型替代。</p>
<details><summary>简要来源与统计定义</summary><p>NOAA/NCEP；31成员含0号控制与1–30扰动。图由GitHub Actions生成，本页只读发布清单和PNG/SVG，不下载GRIB、不执行气旋追踪。此成图为完整+0–120h（GEFS）／+0–240h（AIGEFS），不受其他图块时窗裁切。单个已编号系统均线至少8/31成员；不同系统不混合求均线。保留原始VMAX kt、气压hPa、阈值与颜色；缺值不是零。GEFS原生genesis及AIGEFS本站场L都不是已判定热带气旋；场L的10m矢量风保留m/s，非业务持续风，不拿来替代tracker VMAX。未追踪／缺失成员不代表安全；地图不是官方袭击、登陆或损害概率。</p></details>
</section>
</template>
<style scoped>
.ncep-published{min-width:0;background:white;color:#526f85;padding:12px;border-radius:9px}.ncep-published header,.ncep-controls,.ncep-published nav{display:flex;flex-wrap:wrap;align-items:end;gap:10px 16px}.ncep-published header{justify-content:space-between;align-items:center}.ncep-published h3{font-size:17px;margin:5px 0 12px}.ncep-published label{display:grid;gap:4px;font-size:12px;max-width:100%;min-width:0}.ncep-published select{padding:7px;border:1px solid #cbdce7;border-radius:5px;background:white;max-width:100%;color:inherit}.ncep-published button,.ncep-published a{font-size:12px;color:#287fa8;padding:6px;background:#edf6fb;border-radius:6px}.ncep-published p,.ncep-published details{font-size:11px;line-height:1.8}.ncep-published nav{margin:10px 0}.ncep-error{color:#a54534}.ncep-image-scroll{overflow:auto;max-height:560px;touch-action:pan-x pan-y;background:#edf6fa;border:1px solid #d8e5ed}.ncep-image-scroll img{display:block;height:auto;min-width:100%}.ncep-published:fullscreen{overflow:auto;width:100%;height:100%;padding:18px}.ncep-published:fullscreen .ncep-image-scroll{max-height:80vh}@media(max-width:600px){.ncep-published{padding:7px}.ncep-controls label{flex:1 1 42%}.ncep-image-scroll{max-height:430px}}
</style>
